<?php $title='Checkout';require 'includes/header.php';require_login();$cart=$_SESSION['cart']??[];$items=[];$subtotal=0;foreach($cart as $id=>$qty){$q=$pdo->prepare('SELECT * FROM products WHERE id=?');$q->execute([$id]);if($p=$q->fetch()){$p['qty']=$qty;$p['unit']=$p['discount_price']?:$p['price'];$subtotal+=$p['unit']*$qty;$items[]=$p;}}if(!$items){$_SESSION['flash']='Add an item before checking out.';header('Location: '.url('cart.php'));exit;} $gst=$subtotal*.18;$shipping=$subtotal>=999?0:99;$total=$subtotal+$gst+$shipping;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$fields=['address','phone','city','state','pincode','payment'];foreach($fields as $f)if(empty(trim($_POST[$f]??'')))$errors[]='Please complete all shipping fields.';if(empty($errors)){try{$pdo->beginTransaction();$orderNo='NC'.date('Ymd').strtoupper(bin2hex(random_bytes(3)));$q=$pdo->prepare('INSERT INTO orders(order_no,user_id,address,phone,city,state,pincode,payment_method,subtotal,gst,shipping,total,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,"Pending")');$q->execute([$orderNo,$_SESSION['user']['id'],trim($_POST['address']),trim($_POST['phone']),trim($_POST['city']),trim($_POST['state']),trim($_POST['pincode']),$_POST['payment'],$subtotal,$gst,$shipping,$total]);$oid=$pdo->lastInsertId();$iq=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,price,quantity) VALUES(?,?,?,?,?)');foreach($items as $p){$iq->execute([$oid,$p['id'],$p['name'],$p['unit'],$p['qty']]);$pdo->prepare('UPDATE products SET stock=GREATEST(0,stock-?) WHERE id=?')->execute([$p['qty'],$p['id']]);}$pdo->prepare('INSERT INTO payments(order_id,method,amount,status) VALUES(?,?,?,?)')->execute([$oid,$_POST['payment'],$total,$_POST['payment']==='Cash on Delivery'?'Pending':'Paid']);$pdo->commit();unset($_SESSION['cart']);header('Location: '.url('orders.php?success='.$oid));exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]='Checkout could not be completed. Please try again.';}}} ?>
<h1 class="section-title mb-4">Checkout</h1><?php foreach($errors??[] as $e):?><div class="alert alert-danger"><?=e($e)?></div><?php endforeach;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="row g-4"><div class="col-lg-8"><div class="card border-0 shadow-sm p-4"><h5>Shipping details</h5><div class="row g-3 mt-1"><div class="col-12"><label class="form-label">Address</label><textarea name="address" class="form-control" required></textarea></div><div class="col-md-6"><label class="form-label">Phone</label><input name="phone" class="form-control" required></div><div class="col-md-6"><label class="form-label">City</label><input name="city" class="form-control" required></div><div class="col-md-6"><label class="form-label">State</label><input name="state" class="form-control" required></div><div class="col-md-6"><label class="form-label">Pincode</label><input name="pincode" class="form-control" required></div></div><h5 class="mt-4">Payment method</h5><?php foreach(['Cash on Delivery','UPI','Credit Card (Demo)','Debit Card (Demo)'] as $m):?><div class="form-check"><input class="form-check-input" type="radio" name="payment" value="<?=$m?>" <?=$m==='Cash on Delivery'?'checked':''?>><label class="form-check-label"><?=$m?></label></div><?php endforeach;?></div></div><div class="col-lg-4"><div class="card border-0 shadow-sm p-4"><h5>Order total</h5><p class="d-flex justify-content-between"><span>Items</span><span><?=money($subtotal)?></span></p><p class="d-flex justify-content-between"><span>GST</span><span><?=money($gst)?></span></p><p class="d-flex justify-content-between"><span>Shipping</span><span><?=money($shipping)?></span></p><hr><h5 class="d-flex justify-content-between"><span>Total</span><span class="price"><?=money($total)?></span></h5><button class="btn btn-primary w-100 rounded-pill mt-3">Place order</button></div></div></div></form><?php require 'includes/footer.php'; ?>
